ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"query": {
    "aggregate": p('mongo-db-sapi.collections.services-fija'),
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": {
        	"Id_Cuenta_Servicio": vars.requestOrder.service.serviceAccountId
        }
      }
    ],
    "cursor": {}
  }
}

%dw 2.0
output application/json
---
{
	ruleId: p('rules-id.data-service'),
	isValid: false,
	detailEvaluated: [
		{
	    "evaluateId": "Cuenta_Servicio",
	    "isValid": false,
	    "detail": "Numero de cuenta de servicio: "++ (vars.requestOrder.service.serviceAccountId default "") ++" no existe"
  		}
	]
}
